reviewer_comment:
An equivalent C program works:
```julia
julia> cc = `cc`;

julia> program = raw"""
       #define _GNU_SOURCE
       #include <dlfcn.h>
       #include <stdio.h>
       #include <stdlib.h>

       int main(void) {
           void *h = dlopen("./libccalltest.so", RTLD_LAZY);
           if (!h) {
               fprintf(stderr, "dlopen failed: %s\n", dlerror());
               return 1;
           }

           dlerror(); // clear any existing error

           // function pointer type for sqrt(double) -> double
           typedef double (*sqrt_fn)(double);

           sqrt_fn my_sqrt = (sqrt_fn)dlsym(h, "sqrt");
           const char *err = dlerror();
           if (err) {
               fprintf(stderr, "dlsym failed: %s\n", err);
               dlclose(h);
               return 1;
           }

           double x = 2.0;
           double y = my_sqrt(x);
           printf("sqrt(%g) = %.17g\n", x, y);

           dlclose(h);
           return 0;
       }
       """;

julia> run(pipeline(`$(cc) -x c -fPIC -shared -o libccalltest.so -lm -`; stdin=devnull));

julia> run(pipeline(`$(cc) -x c -L. -lccalltest -o test -`; stdin=IOBuffer(program)));

julia> run(`./test`);
sqrt(2) = 1.4142135623730951

julia> @ccall "./libccalltest.so".sqrt(2.0::Cdouble)::Cdouble
ERROR: could not load symbol "sqrt":
dlsym(0x392efeb41, sqrt): symbol not found
Stacktrace:
 [1] top-level scope
   @ ./REPL[10]:1
```
So yes, we shouldn't be stricter than what normal C applications can do.  Thanks for fixing it!

