+/**
+ * Universal clipboard utility with modern API and fallback support
+ * Handles various security contexts and browser compatibility issues
+ */
+
+export interface ClipboardResult {
+  success: boolean;
+  method: 'clipboard-api' | 'execCommand' | 'failed';
+  error?: string;
+}
+
+/**
+ * Copy text to clipboard with automatic fallback mechanisms
+ * @param text - Text to copy to clipboard
+ * @returns Promise<ClipboardResult> - Result of the copy operation
+ */
+export const copyToClipboard = async (text: string): Promise<ClipboardResult> => {
+  // Try modern clipboard API first with SSR-safe guards
+  if (
+    typeof navigator !== 'undefined' &&
+    navigator.clipboard &&
+    navigator.clipboard.writeText
+  ) {
+    try {
+      await navigator.clipboard.writeText(text);
+      return { success: true, method: 'clipboard-api' };
+    } catch (error) {
+      console.warn('Clipboard API failed, trying fallback:', error);
+    }
+  }
+
+  // Fallback to document.execCommand for older browsers or insecure contexts
+  // Add SSR guards for document access
+  if (typeof document === 'undefined') {
+    return {
+      success: false,
+      method: 'failed',
+      error: 'Running in server-side environment - clipboard not available'
+    };
+  }
+
+  let textarea: HTMLTextAreaElement | null = null;
+  try {
+    // Ensure document.body exists before proceeding
+    if (!document.body) {
+      return {
+        success: false,
+        method: 'failed',
+        error: 'document.body is not available'
+      };
+    }
+
+    textarea = document.createElement('textarea');
+    textarea.value = text;
+    textarea.style.position = 'fixed';
+    textarea.style.top = '-9999px';
+    textarea.style.left = '-9999px';
+    textarea.style.opacity = '0';
+    textarea.style.pointerEvents = 'none';
+    textarea.setAttribute('readonly', '');
+    textarea.setAttribute('aria-hidden', 'true');
+
+    document.body.appendChild(textarea);
+    textarea.s

reviewer_comment:
Creating a new map for currentNodes on every Pick() call could impact performance in high-throughput scenarios. Consider optimizing this by only performing cleanup when the node list changes, rather than on every pick operation.
```suggestion
	// Check if the node list has changed
	if len(p.lastNodes) != len(nodes) || !equalNodes(p.lastNodes, nodes) {
		// Update lastNodes
		p.lastNodes = make([]selector.WeightedNode, len(nodes))
		copy(p.lastNodes, nodes)

		// Create a set of current node addresses for cleanup
		currentNodes := make(map[string]bool)
		for _, node := range nodes {
			currentNodes[node.Address()] = true
		}

		// Clean up stale entries from currentWeight map
		for address := range p.currentWeight {
			if !currentNodes[address] {
				delete(p.currentWeight, address)
			}
		}
```

