When an unmarshalling error occurs in streaming mode after some chunks have already been sent (line 241-244), returning with c.JSON will mix JSON error responses with the newline-delimited streaming format, potentially confusing clients. Consider sending errors in the same streaming format when prompt.Stream is true, or documenting this edge case behavior.
```suggestion
			if prompt.Stream {
				// In streaming mode, send the error in the same streaming format
				_ = writeOllamaResponse(c, prompt.Model, "Error: failed to parse upstream response", false)
			} else {
				c.JSON(http.StatusInternalServerError, gin.H{"error": "testing endpoint"})
			}
			return
		}
		if fabricResponse.Type == "error" {
			if prompt.Stream {
				// In streaming mode, send the upstream error as a streamed chunk
				_ = writeOllamaResponse(c, prompt.Model, fmt.Sprintf("Error: %s", fabricResponse.Content), false)
			} else {
				c.JSON(http.StatusInternalServerError, gin.H{"error": fabricResponse.Content})
			}
